INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_soc_fresher_001', 'soc', 'triage', 'fresher', 'An alert fires: several failed SSH logins from one IP, then a successful one. What do you do first?', 'Establish scope before acting. Confirm the source IP and whether it is internal or external, which account succeeded, and whether that account normally logs in from there. Check what the session did after login, especially privilege changes. Do not close it as a brute force just because the pattern looks familiar.', '2026-11-19T18:39:15.814Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_fresher_001_f1', 'q_soc_fresher_001', 1, 'The successful login was a different account from the failed ones. Does that change your read?', 'Yes, and it makes it worse. Failures on one account and success on another suggests either credential spraying across accounts or an attacker who already held working credentials and the failures were noise. Pivot to: what else did that account touch, and were there successes elsewhere you have not alerted on.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_fresher_001_f2', 'q_soc_fresher_001', 2, 'The account belongs to a developer who says it was him. How do you verify?', 'Do not take the word alone. Match the source IP against his known locations and VPN logs, check the user agent or client version, confirm the timing against his working hours, and ask what he was doing at that minute. If he was working, the failures still need explaining, because a legitimate user rarely fails three times on a different account.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_soc_fresher_002', 'soc', 'detection', 'fresher', 'What is the difference between an IDS and an IPS?', 'An IDS observes and alerts; an IPS sits inline and can drop. The real difference is consequence: a false positive on an IDS is noise, a false positive on an IPS is an outage. That is why IPS rules are deployed in detect mode first and promoted to block only once the noise is understood.', '2026-11-19T18:39:15.814Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_fresher_002_f1', 'q_soc_fresher_002', 1, 'Your IPS is dropping legitimate traffic. What do you change first?', 'Move the offending signature to alert-only rather than disabling the whole policy or the device. That stops the damage while keeping visibility. Then identify the exact rule and the traffic it matched before you decide whether to tune the rule, exempt the source, or fix the application.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_fresher_002_f2', 'q_soc_fresher_002', 2, 'Who signs off on that change, and what goes in the ticket?', 'Change goes through whoever owns the control, usually network or security engineering, with the application owner informed. The ticket records which rule, why it was changed, what traffic it was matching, what the temporary state is, when it will be reviewed, and who approved it. A tuning change with no review date becomes a permanent blind spot.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_soc_fresher_003', 'soc', 'phishing', 'fresher', 'A user reports a phishing email. Walk me through what you do.', 'Preserve the original with headers before anything else. Pull the sender, reply-to, originating IP, authentication results, links and attachments. Detonate links and attachments in a sandbox, never on your own machine. Then determine who else received it and whether anyone interacted.', '2026-11-19T18:39:15.814Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_fresher_003_f1', 'q_soc_fresher_003', 1, 'The user already clicked the link. What changes?', 'It moves from analysis to containment. Find out what the page asked for and whether credentials were entered. If they were, reset the password and invalidate active sessions and tokens, not just the password. Check for mailbox rules created after the click, which is the usual first move after a mailbox compromise.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_fresher_003_f2', 'q_soc_fresher_003', 2, 'How do you find out who else received it?', 'Search the mail gateway or mail platform by sender, subject, originating IP and URL, not just the exact subject line, because the campaign will vary it. Then check who opened and who clicked, and purge the message from remaining mailboxes. Report the delivered-versus-clicked numbers, because that is what the business will ask.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_soc_mid_004', 'soc', 'endpoint', 'mid', 'Your EDR flags a signed binary behaving unusually. How do you triage it?', 'A valid signature says who built it, not that the behaviour is safe. Look at what the process actually did: parent process, command line, network destinations, files written, persistence created. Signed binaries get abused for living-off-the-land execution, so the behaviour chain matters more than the reputation score.', '2026-11-19T18:39:15.814Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_mid_004_f1', 'q_soc_mid_004', 1, 'The signature is valid and the vendor is well known. Still suspicious?', 'Yes, if the behaviour does not match what that binary exists to do. A known-good tool launched by an unusual parent, with arguments that pull a remote payload, is a classic abuse pattern. Treat the question as whether this execution is expected on this host, not whether the file is malicious in general.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_mid_004_f2', 'q_soc_mid_004', 2, 'You decide to contain. What exactly do you contain, and what do you tell the business?', 'Isolate the host at the network level while keeping your own access for investigation, rather than powering it off and losing memory. Block the command-and-control destination at the egress point. Tell the business which host, what it can no longer do, what the user should expect, and what you need from them, in plain terms and with a time you will next update them.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_soc_mid_005', 'soc', 'tuning', 'mid', 'How do you tune a noisy detection rule without going blind to the thing it was built for?', 'Start from what the rule is supposed to catch, then measure what it is actually matching. Narrow by the attribute that separates benign from malicious, usually a specific process, account or destination, rather than lowering severity or widening the time window. Record the exclusion and why, so the next analyst can see the gap you accepted.', '2026-11-19T18:39:15.814Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_mid_005_f1', 'q_soc_mid_005', 1, 'The noise comes from one application the business will not change. Now what?', 'Scope the exclusion as tightly as the application allows: that service account, on those hosts, to those destinations. Then add a narrower compensating rule that would still fire if the excluded pattern were abused, and document the residual risk so it is a decision on record rather than a silent hole.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_mid_005_f2', 'q_soc_mid_005', 2, 'Six months later, how do you know the tuning is still right?', 'Review exclusions on a schedule and test them. Confirm the application still behaves the way the exclusion assumes, and validate the rule still fires on the original behaviour using an atomic test. An exclusion that nobody has revisited is a control that nobody can vouch for.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_network_fresher_006', 'network', 'tcp', 'fresher', 'Explain the TCP three-way handshake.', 'The client sends SYN with its initial sequence number, the server replies SYN-ACK acknowledging it and sending its own, the client replies ACK. After that the connection is established. The point of the exchange is that both sides agree on sequence numbers and both prove they can receive, which is what makes blind spoofing hard.', '2026-11-19T18:39:15.814Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_fresher_006_f1', 'q_network_fresher_006', 1, 'You see thousands of SYNs with no completing ACKs. What is happening?', 'Half-open connections, which is either a SYN flood or a scan. A flood aims to exhaust the backlog; a scan is looking for open ports and usually comes with RSTs. Distinguish by volume, source spread, and whether the destination ports vary or stay fixed.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_fresher_006_f2', 'q_network_fresher_006', 2, 'How would you confirm it, and what would you do about it?', 'Confirm with a capture and connection-state counters on the host, checking backlog and half-open counts rather than relying on the alert alone. Mitigation is SYN cookies, rate limiting at the edge, and upstream filtering if the volume exceeds your link. If it is a scan rather than a flood, the response is blocking and investigating the source, not tuning the stack.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_network_fresher_007', 'network', 'firewalls', 'fresher', 'What is the difference between a stateful and a stateless firewall?', 'A stateless firewall evaluates each packet against rules in isolation. A stateful firewall tracks connections, so return traffic for an established session is allowed without a matching inbound rule. Stateful is why you do not have to write a rule for every ephemeral port on the way back.', '2026-11-19T18:39:15.814Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_fresher_007_f1', 'q_network_fresher_007', 1, 'Which would you put at the perimeter, and why?', 'Stateful, because the perimeter is where you need to distinguish solicited return traffic from unsolicited inbound traffic. A stateless filter at the edge either blocks legitimate replies or forces rules so broad that they stop meaning anything.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_fresher_007_f2', 'q_network_fresher_007', 2, 'What does stateful inspection cost you that stateless does not?', 'Memory and a finite connection table, which is itself a target: fill the table and the device starts dropping or failing open. It also costs per-connection processing, which matters at high throughput, and it makes failover harder because state has to be synchronised or sessions break.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_network_mid_008', 'network', 'segmentation', 'mid', 'You are asked to segment a flat corporate network. Where do you start?', 'Start with what talks to what, not with the diagram you wish you had. Collect flow data for long enough to cover monthly jobs, group assets by function and sensitivity, then design the smallest number of zones that separate the things that must not reach each other. Enforce in monitor mode first.', '2026-11-19T18:39:15.814Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_mid_008_f1', 'q_network_mid_008', 1, 'Finance says segmentation will break their reporting tool. What now?', 'Get the actual flows rather than the claim: which source, which destination, which port, how often. Usually it is a handful of flows that can be allowed explicitly. If the tool genuinely needs broad access, that is a documented exception with a compensating control and an owner, not a reason to abandon the zone.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_mid_008_f2', 'q_network_mid_008', 2, 'How do you prove the segmentation actually holds?', 'Test it from inside each zone: attempt the connections that should fail and confirm they fail at the enforcement point, not just that nobody has complained. Keep the test as a repeatable check, because firewall rule sprawl quietly re-flattens a network over a year.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_network_mid_009', 'network', 'dns', 'mid', 'You see repeated TXT queries to a domain registered three days ago. What is your read?', 'That pattern fits DNS tunnelling or beaconing: TXT records carry more data than A records, and a newly registered domain is a common indicator. Look at query volume, subdomain entropy, timing regularity, and which host is asking. Regular intervals suggest automation rather than a user.', '2026-11-19T18:39:15.814Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_mid_009_f1', 'q_network_mid_009', 1, 'How would you confirm exfiltration rather than a misconfigured tool?', 'Look at the content and direction. Tunnelling shows high-entropy, long subdomain labels and sustained two-way volume; a misconfigured security or telemetry tool usually queries a vendor domain with predictable labels. Identify the process making the queries on the host, which settles it faster than packet analysis alone.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_mid_009_f2', 'q_network_mid_009', 2, 'What do you block, and what breaks if you are wrong?', 'Sinkhole the specific domain rather than blocking TXT records or the resolver wholesale. If you are wrong, you break one tool and find out within minutes, which is recoverable. Blocking at the resolver level breaks name resolution for everyone, which is an outage you caused while chasing a maybe.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_pentest_fresher_010', 'pentest', 'web', 'fresher', 'Which OWASP Top 10 risk do you see most often in real applications, and why that one?', 'Broken access control, because it is a logic problem rather than a pattern a scanner matches. Authentication is usually handled by a framework; authorisation is written per endpoint by hand, so one missing ownership check in one route is enough. Answer with the reason it recurs, not just the name.', '2026-11-19T18:39:15.814Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_fresher_010_f1', 'q_pentest_fresher_010', 1, 'Show me how you would test for it on a login-protected endpoint.', 'Authenticate as a low-privilege user, capture a request that references an object you own, then replay it with another identifier while keeping your own session. If you get someone else''s data back, that is the finding. Repeat for write operations, since read and write are often guarded differently.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_fresher_010_f2', 'q_pentest_fresher_010', 2, 'The developer says the WAF blocks it. How do you respond?', 'Demonstrate it through the WAF, from the same path a real user takes. A WAF matches patterns; an authorisation flaw is a valid, well-formed request that the application should have refused. If it still works end to end, the WAF argument is answered without a debate.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_pentest_fresher_011', 'pentest', 'scope', 'fresher', 'What is the difference between a vulnerability scan and a penetration test?', 'A scan enumerates known issues against signatures and reports what might be exploitable. A test attempts to prove impact by chaining findings the way an attacker would. The distinction that matters to a client is that a scan tells you what is present and a test tells you what it is worth.', '2026-11-19T18:39:15.814Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_fresher_011_f1', 'q_pentest_fresher_011', 1, 'A client wants a pentest but the budget fits a scan. What do you tell them?', 'Be direct that a scan will not answer the question they are asking, then offer the honest middle: a scan plus manual validation of the highest-impact findings, scoped to the part of the estate that carries the real risk. Selling a scan as a test is how firms lose clients at the next breach.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_fresher_011_f2', 'q_pentest_fresher_011', 2, 'What goes into the report that a scanner cannot produce?', 'The chain and the business consequence: how three medium findings combined into access to a specific dataset, what an attacker gets at the end, and what to fix first given their constraints. A scanner produces severity; a tester produces a prioritised story the client can act on.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_pentest_mid_012', 'pentest', 'engagement', 'mid', 'You get a shell on a web server during an engagement. What do you do next?', 'Before anything else, confirm the host is in scope and note the time, the access path and what you did, because that record is what makes the finding defensible. Then establish where you are: user context, host role, what the box can reach. Collect what proves impact rather than expanding access for its own sake.', '2026-11-19T18:39:15.814Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_mid_012_f1', 'q_pentest_mid_012', 1, 'The scope says web application only. Does that change anything?', 'Yes. A shell on the host may already be at or past the boundary. Stop, document the access as the finding, and get written confirmation from the client before touching the host further. The impact is already proven; continuing without authorisation turns a good finding into a contract problem.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_mid_012_f2', 'q_pentest_mid_012', 2, 'You find evidence someone else was already in there. Now what?', 'Stop testing and notify the client immediately through the agreed escalation path, because this is now a live incident and not a test. Preserve what you saw, change nothing, and do not investigate further unless they ask you to. Your own actions also need to be separable from the intruder''s in their timeline.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_pentest_mid_013', 'pentest', 'reporting', 'mid', 'How do you decide what to report as critical?', 'Critical is about reachable impact, not CVSS alone. Ask what an attacker gets, who can reach it, and what is required to pull it off. An unauthenticated path to customer data is critical; the same bug behind an admin login on an internal network usually is not. State the reasoning so the rating can be argued with.', '2026-11-19T18:39:15.814Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_mid_013_f1', 'q_pentest_mid_013', 1, 'The client disagrees with your severity. How do you handle it?', 'Ask what they know that you do not, because they often do: a compensating control, a network boundary, data that is not what it looks like. If their information changes the exposure, adjust and say why. If it does not, keep the rating and record their position in the report rather than quietly lowering it.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_mid_013_f2', 'q_pentest_mid_013', 2, 'What makes a finding actionable rather than just alarming?', 'A reproduction a developer can follow, the specific location in the code or configuration, the fix stated in their stack rather than in general terms, and a way to verify the fix worked. Without those, a critical finding sits in a backlog for a year.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_cloud_fresher_014', 'cloud', 'fundamentals', 'fresher', 'Explain the shared responsibility model.', 'The provider secures the infrastructure the service runs on; the customer secures what they put into it and how they configure it. The line moves by service type: with managed services the provider takes on more of the stack, but identity, access and data configuration stay with the customer in every model.', '2026-11-19T18:39:15.814Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_fresher_014_f1', 'q_cloud_fresher_014', 1, 'Who is responsible for a storage bucket left public?', 'The customer. The provider gives the access controls and increasingly defaults them to private, but the configuration is the customer''s. Nearly every public-bucket incident is a configuration decision, not a provider failure.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_fresher_014_f2', 'q_cloud_fresher_014', 2, 'Name two things people assume the provider handles but it does not.', 'Backups and retention for data in managed services, which are usually opt-in and the customer''s to configure and test. And logging: control-plane and data-plane logs often need enabling and paying for, and if nobody turned them on there is no investigation after an incident.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_cloud_fresher_015', 'cloud', 'storage', 'fresher', 'A storage bucket is publicly readable. Walk me through the fix.', 'First establish exposure: what is in it, for how long, and whether access logs show reads from outside. Then remove public access at the account level rather than object by object. Only after that work out how it got that way, because the same mechanism has usually produced others.', '2026-11-19T18:39:15.814Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_fresher_015_f1', 'q_cloud_fresher_015', 1, 'The bucket serves a static website that genuinely must stay public. Now what?', 'Separate what must be public from what must not: a bucket that holds only published assets, with everything else moved out. Serve it through a CDN with the origin locked to the CDN rather than exposing the bucket directly, and keep account-level blocks on every other bucket.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_fresher_015_f2', 'q_cloud_fresher_015', 2, 'How do you stop the next one happening?', 'Enforcement rather than a reminder: account-level public access blocks, a policy that refuses to create public buckets, and a check in the deployment pipeline so it fails before it ships. Then alert on any change to that configuration, because the control is only as good as the notice you get when someone disables it.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_cloud_mid_016', 'cloud', 'secrets', 'mid', 'How do you handle secrets in a cloud application?', 'Secrets live in a managed secret store, injected at runtime, never in the repository, the image, or environment variables baked into a build. Access is scoped by identity, reads are logged, and rotation is automated. Where the platform supports workload identity, use it and remove the long-lived credential entirely.', '2026-11-19T18:39:15.814Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_mid_016_f1', 'q_cloud_mid_016', 1, 'A developer has committed a key to a public repository. What is your first hour?', 'Rotate first, investigate second. Revoke the key immediately, because removing the commit does not remove it from forks, caches or anyone who already scraped it. Then pull the audit log for everything that key did from the moment it was pushed, and only then deal with the repository history and the developer.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_mid_016_f2', 'q_cloud_mid_016', 2, 'How do you know the key was not used before you rotated it?', 'The provider''s audit log, filtered by that credential, from the push timestamp to revocation. Look for calls from unfamiliar addresses, unusual regions, enumeration patterns, and any change to identity or logging configuration. If logging was not enabled for that service, say so plainly: you cannot prove a negative, and the answer is that you do not know.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_cloud_mid_017', 'cloud', 'iam', 'mid', 'An IAM role has wildcard permissions. How do you fix it without breaking production?', 'Do not guess at a replacement policy. Determine what the role actually uses from access logs over a period long enough to include periodic jobs, build a least-privilege policy from observed calls, then run it alongside in a mode that reports denials before enforcing. Narrow in stages rather than in one change.', '2026-11-19T18:39:15.814Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_mid_017_f1', 'q_cloud_mid_017', 1, 'Nobody knows what the role actually uses. How do you find out?', 'Query the control-plane audit log for calls made by that role, grouped by service and action, over at least a full billing or reporting cycle. Most providers also expose last-accessed data per service, which gives you the unused surface immediately. Use both: one shows what is used, the other shows what safely is not.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_mid_017_f2', 'q_cloud_mid_017', 2, 'How do you keep it from drifting back to wildcards?', 'Policy as code with review, a guardrail at the organisation level that refuses wildcard actions on sensitive services, and an alert on policy changes. Drift happens when someone is debugging at night, so the control has to be a refusal at deploy time, not a quarterly audit.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_grc_fresher_018', 'grc', 'documents', 'fresher', 'What is the difference between a policy, a standard, and a procedure?', 'A policy states intent and is approved by leadership. A standard makes it measurable: the specific requirement something must meet. A procedure is the steps someone follows to meet it. Policies change rarely, standards change with technology, procedures change with tooling.', '2026-11-19T18:39:15.814Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_fresher_018_f1', 'q_grc_fresher_018', 1, 'An auditor asks for evidence that a policy is followed. What do you show?', 'Not the policy. Show output from the control: configuration exports, ticket records, access review sign-offs, log samples across the audit period. Evidence is what the system produced while nobody was watching, not a document describing what should happen.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_fresher_018_f2', 'q_grc_fresher_018', 2, 'The evidence does not exist. What do you do?', 'Say so rather than assembling something after the fact, which is how a finding becomes a fraud problem. Record it as a gap, start generating the evidence now, and give a remediation date. Auditors handle known gaps with a plan routinely; they handle fabricated evidence very differently.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_grc_fresher_019', 'grc', 'risk', 'fresher', 'What does a risk register do, and what makes a bad one?', 'It records risks the organisation has decided to track, with an owner, a rating, a treatment decision and a review date. A bad one is a list of vulnerabilities with no owner, no decision and no date, which makes it an inventory nobody acts on rather than a tool for allocating attention.', '2026-11-19T18:39:15.814Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_fresher_019_f1', 'q_grc_fresher_019', 1, 'A risk has been marked in progress for two years. How do you handle it?', 'Treat the status as false and get a decision. Either it is genuinely being treated, in which case it needs a plan with dates, or the organisation has accepted it, in which case say so explicitly with a named accepting owner. A permanent in-progress entry is an unmade decision hiding as work.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_fresher_019_f2', 'q_grc_fresher_019', 2, 'Who should own a risk, security or the business?', 'The business function that carries the consequence, because they are the ones who can accept it or fund the fix. Security owns the assessment, the recommendation and the follow-up. When security owns the risk itself, acceptance becomes invisible and nothing gets prioritised against revenue.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_grc_mid_020', 'grc', 'certification', 'mid', 'You are asked to get the company ISO 27001 certified in six months. What is your first move?', 'Define the scope, because everything else follows from it. Which entity, which locations, which systems, which data. Then run a gap assessment against the controls in that scope to find out what already exists in practice but is undocumented, which is usually more than leadership expects.', '2026-11-19T18:39:15.814Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_mid_020_f1', 'q_grc_mid_020', 1, 'Leadership wants certification without changing how teams work. What do you say?', 'Be straight: certification audits evidence of operating controls, so if nothing changes there is nothing to evidence. Then make it tractable by scoping tightly to the part of the business that needs the certificate commercially, rather than diluting the controls across the whole company.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_mid_020_f2', 'q_grc_mid_020', 2, 'Where do most first-time certifications actually fail?', 'Not on the controls, on the management system: risk assessment that was done once and never revisited, internal audit that did not happen, management review with no record, and corrective actions left open. Those are the clauses auditors check first and the ones teams treat as paperwork.');
